const demoUnit={id:"sync",isDemo:true,title:"进程同步：从竞态条件到信号量",course:"体验示例",chapter:"并发与同步",duration:"90 分钟",status:"示例",completion:64,updated:"内置示例",overview:"学生真正需要理解的不是信号量 API，而是并发执行如何破坏原本正确的顺序假设。本单元从一次可观察的丢失更新开始，引出临界区约束，再让学生用信号量修复问题。",objectives:["能够通过执行轨迹解释竞态条件产生的必要条件","能够区分互斥、同步与忙等待解决的不同问题","能够根据临界区需求设计基本的信号量 P/V 操作","能够从反例中识别死锁或顺序约束错误"],keyPoints:[{title:"竞态条件与不可再现性",logic:"多个执行主体访问共享状态，最终结果取决于不可预测的执行交错。",misconception:"程序每一行都正确，因此并发运行结果也必然正确。",question:"两次加一为什么可能只得到一？"},{title:"临界区与互斥约束",logic:"真正需要保护的是访问共享不变量的代码区间，而不是整个线程。",misconception:"加锁范围越大越安全，不需要考虑并发度。",question:"锁应该从哪里开始、在哪里释放？"},{title:"信号量的状态语义",logic:"计数值与等待队列共同表达可用资源及受阻执行者，而不仅是一个整数。",misconception:"P/V 只是对变量做减一和加一。",question:"当值为 0 时，P 操作实际改变了什么？"},{title:"同步顺序与死锁风险",logic:"多个资源上的请求与持有关系可能形成循环等待，使所有参与者永久阻塞。",misconception:"只要每次操作都加锁就不会出错。",question:"互斥正确为何仍可能无法继续执行？"}],lesson:{flow:[{phase:"冲突引入",minutes:10,teacherAction:"运行同一段程序多次，展示不同结果；不先解释原因。",studentAction:"预测输出并记录出现分歧的位置。"},{phase:"机制拆解",minutes:20,teacherAction:"单步播放两个线程的读—改—写交错。",studentAction:"在时间轴上标出共享状态失去一致性的时刻。"},{phase:"概念建模",minutes:20,teacherAction:"由反例归纳临界区、互斥和原子性。",studentAction:"比较三种加锁边界，判断正确性与并发度。"},{phase:"方法迁移",minutes:25,teacherAction:"引入信号量状态语义与 P/V 操作。",studentAction:"小组完成生产者—消费者的顺序约束。"},{phase:"诊断收束",minutes:15,teacherAction:"展示一个会死锁的修复方案。",studentAction:"解释错误原因并提交最小修改。"}],questions:[{prompt:"线程 A 和 B 都执行 x=x+1，什么执行顺序会让最终结果为 1？",answerCue:"两者在任一方写回前都读取旧值 0。",misconception:"认为加一语句天然是原子的。"},{prompt:"把锁加在线程入口是否正确？如果正确，为什么仍不是好设计？",answerCue:"能保证互斥，但锁范围过大，损失无关代码的并发执行。",misconception:"把安全性和并发效率混为一谈。"},{prompt:"两个信号量分别保护两个资源，为何仍可能死锁？",answerCue:"不同线程以相反顺序持有并请求资源，形成循环等待。",misconception:"认为使用锁就自动消除全部并发错误。"}],afterClass:["根据课堂投票结果，判断下节课是否需要补充原子操作","收集学生画出的执行时间线，聚类其对读取/写回边界的误解","将死锁反例改为实验测试用例，加入下一次作业"]},resources:[{type:"motion",title:"丢失更新：执行交错可视化",purpose:"让学生直接看到两个局部正确操作如何共同破坏共享状态。",status:"待确认"},{type:"code",title:"共享计数器单步追踪器",purpose:"切换不同调度序列并观察变量、寄存器与写回结果。",status:"草稿"},{type:"lab",title:"信号量边界实验",purpose:"比较三种临界区设计的正确性和并发效率。",status:"已生成"},{type:"case",title:"死锁诊断卡片",purpose:"从请求—持有图中识别循环等待并提出最小修复。",status:"已生成"}],animations:[{id:"race",title:"竞态条件为何导致丢失更新",teachingQuestion:"两个线程都执行加一，为什么结果可能只增加一次？",narration:"线程 A 与线程 B 先后读取同一个旧值，各自在局部完成加一；后写回的结果覆盖先写回的结果，因此两次操作只留下了一次更新。",scene:demoScene}]};
