function loadUnits(){try{const saved=JSON.parse(localStorage.getItem(storeKey)||"[]");return Array.isArray(saved)?saved.filter(unit=>unit&&typeof unit==='object'):[]}catch{return []}}
function loadCourses(units){let saved=[];try{saved=JSON.parse(localStorage.getItem(courseStoreKey)||"[]")}catch{}const byName=new Map(saved.filter(course=>course?.name).map(course=>[course.name,course]));units.filter(unit=>!unit.isDemo&&unit.course&&unit.course!=="暂不归入课程").forEach(unit=>{if(!byName.has(unit.course))byName.set(unit.course,{id:"c"+Math.random().toString(36).slice(2),name:unit.course,code:"",description:""})});return [...byName.values()]}
function persist(){localStorage.setItem(storeKey,JSON.stringify(state.units))}
function persistCourses(){localStorage.setItem(courseStoreKey,JSON.stringify(state.courses))}
if(state.courses.length)persistCourses();
function syncCourseSelect(preferred){const select=$("#sourceCourse");if(!select)return;const current=preferred||select.value||"暂不归入课程";select.innerHTML=[...state.courses.map(course=>course.name),"暂不归入课程"].map(name=>`<option>${esc(name)}</option>`).join("");select.value=[...select.options].some(option=>option.value===current)?current:"暂不归入课程"}
function showToast(text){const t=$("#toast");t.textContent=text;t.classList.remove("hidden");setTimeout(()=>t.classList.add("hidden"),2600)}
let editingCourseId=null;
function openCourseEditor(courseId=null){const course=state.courses.find(item=>item.id===courseId);editingCourseId=course?.id||null;$("#courseDialogTitle").textContent=course?"编辑课程":"新建课程";$("#courseName").value=course?.name||"";$("#courseCode").value=course?.code||"";$("#courseDescription").value=course?.description||"";$("#courseError").classList.add("hidden");if(!$("#courseDialog").open)$("#courseDialog").showModal();setTimeout(()=>$("#courseName").focus(),0)}
function saveCourse(){const name=$("#courseName").value.trim(),code=$("#courseCode").value.trim(),description=$("#courseDescription").value.trim(),duplicate=state.courses.find(course=>course.name.toLowerCase()===name.toLowerCase()&&course.id!==editingCourseId);if(!name){$("#courseError span").textContent="请填写课程名称。";$("#courseError").classList.remove("hidden");return}if(duplicate){$("#courseError span").textContent="已经存在同名课程。";$("#courseError").classList.remove("hidden");return}const existing=state.courses.find(course=>course.id===editingCourseId);if(existing){const oldName=existing.name;Object.assign(existing,{name,code,description,updatedAt:new Date().toISOString()});state.units.filter(unit=>!unit.isDemo&&unit.course===oldName).forEach(unit=>unit.course=name);persist()}else state.courses.push({id:crypto.randomUUID(),name,code,description,unitOrder:[],createdAt:new Date().toISOString()});persistCourses();syncCourseSelect(name);renderCollections();if(selectedCourseName){selectedCourseName=name;renderCourseMap(name)}$("#courseDialog").close();showToast(existing?"课程信息和所属教学单元已更新":"课程已创建，可开始添加教学单元")}
function recordUnitVersion(unit,title,detail){unit.versionHistory=[{id:crypto.randomUUID(),createdAt:new Date().toISOString(),title,detail,snapshot:createUnitSnapshot(unit)},...(Array.isArray(unit.versionHistory)?unit.versionHistory:[])].slice(0,30)}
function ensureVersionBaseline(unit){if(!unit.isDemo&&!(unit.versionHistory||[]).some(version=>version.snapshot))recordUnitVersion(unit,"初始内容快照","启用可恢复版本时保存的教学单元内容。")}
function copyDemoUnit(){const copy=normalizeUnit({...structuredClone(demoUnit),id:"u"+Date.now(),isDemo:false,course:"暂不归入课程",status:"草稿",completion:64,updated:"刚刚",title:`${demoUnit.title}（副本）`,versionHistory:[]});recordUnitVersion(copy,"从体验示例创建副本","已创建可独立修改的个人教学单元。");state.units.unshift(copy);state.currentUnit=copy;persist();renderCollections();return copy}
let pendingRestoreVersionId="";
function restoreUnitVersion(versionId){const unit=state.currentUnit,target=(unit.versionHistory||[]).find(version=>version.id===versionId);if(!target?.snapshot)return showToast("这个旧记录没有可恢复的内容快照");pendingRestoreVersionId=versionId;$("#restoreVersionName").textContent=target.title;$("#restoreVersionTime").textContent=new Date(target.createdAt).toLocaleString("zh-CN");$("#restoreVersionDialog").showModal()}
function confirmRestoreUnitVersion(){const unit=state.currentUnit,target=(unit.versionHistory||[]).find(version=>version.id===pendingRestoreVersionId);if(!target?.snapshot){$("#restoreVersionDialog").close();pendingRestoreVersionId="";return showToast("这个版本已经不可用，请刷新后重试")}recordUnitVersion(unit,"恢复前自动备份",`恢复“${target.title}”之前保存的当前内容。`);applyUnitSnapshot(unit,target.snapshot);unit.updated="刚刚";recordUnitVersion(unit,`恢复版本：${target.title}`,`已恢复 ${new Date(target.createdAt).toLocaleString("zh-CN")} 的教学内容；动效独立版本不受影响。`);commitCurrentUnit();renderWorkspace();renderWorkspaceState();renderVersionHistory(unit);$("#restoreVersionDialog").close();pendingRestoreVersionId="";showToast("历史内容已恢复，恢复前状态也已备份")}
function renderVersionHistory(unit){const history=Array.isArray(unit.versionHistory)?unit.versionHistory:[];$("#versionsPanel").innerHTML=`<div class="unit-summary"><h2>版本记录</h2><p>内容版本包含教学概览、知识点、课堂流程、评价与资源；动效使用动画实验室中的独立版本。</p></div><div class="version-timeline">${history.length?history.map((version,index)=>`<article class="version-item"><span>${new Date(version.createdAt).toLocaleString("zh-CN",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit"})} · ${index===0?"当前版本":`历史版本 ${history.length-index}`}</span><h3>${esc(version.title)}</h3><p>${esc(version.detail||"已保存本次修改。")}</p>${version.snapshot&&index>0?`<button class="version-restore" type="button" data-restore-version="${esc(version.id)}"><i class="ph ph-arrow-counter-clockwise"></i> 恢复此版本</button>`:version.snapshot?'<small class="version-snapshot-ready"><i class="ph ph-check-circle"></i> 可恢复内容快照</small>':'<small class="version-snapshot-missing">旧版摘要记录，无内容快照</small>'}</article>`).join(""):`<article class="version-item"><span>${esc(unit.updated||"刚刚")} · 初始版本</span><h3>${unit.partial?"自动保存的中间成果":"教学单元初始版本"}</h3><p>${unit.partial?"保留了分析中断前已经完成的内容。":"打开单元后将自动建立第一份可恢复快照。"}</p></article>`}</div>`;$$('[data-restore-version]').forEach(button=>button.onclick=()=>restoreUnitVersion(button.dataset.restoreVersion))}
