function saveUnitEditor(){const title=$("#unitEditTitle").value.trim(),overview=$("#unitEditOverview").value.trim(),objectives=$("#unitEditObjectives").value.split(/\n+/).map(item=>item.trim()).filter(Boolean);if(!title){$("#unitEditorError span").textContent="请填写教学单元标题。";$("#unitEditorError").classList.remove("hidden");return}if(!overview){$("#unitEditorError span").textContent="请填写这节课真正要解决的问题。";$("#unitEditorError").classList.remove("hidden");return}if(!objectives.length){$("#unitEditorError span").textContent="请至少保留一项学习目标。";$("#unitEditorError").classList.remove("hidden");return}const unit=state.currentUnit,changed=[];if(unit.title!==title)changed.push("标题");if(unit.course!==$("#unitEditCourse").value)changed.push("课程归属");if(unit.duration!==$("#unitEditDuration").value.trim())changed.push("授课时长");if(unit.overview!==overview)changed.push("核心说明");if(JSON.stringify(unit.objectives)!==JSON.stringify(objectives))changed.push("学习目标");Object.assign(unit,{title,course:$("#unitEditCourse").value,duration:$("#unitEditDuration").value.trim()||"90 分钟",overview,objectives,updated:"刚刚"});recordUnitVersion(unit,$("#unitEditNote").value.trim()||"手动完善教学概览",changed.length?`更新了：${changed.join("、")}。`:"确认并保存了当前教学内容。");commitCurrentUnit();renderWorkspace();renderWorkspaceState();renderVersionHistory(unit);$("#breadcrumbs").textContent=`${unit.course} / ${unit.title}`;removeUnitEditorDraft(localStorage,unitEditorDraftKey,activeUnitEditorDraftContext);unitEditorDraftRestored=false;$("#unitEditorDialog").close();showToast("教学单元已保存为新版本")}
