  function setupCourseMap(){const style=document.createElement("link");style.rel="stylesheet";style.href="./course-map.css";document.head.append(style);const queueStyle=document.createElement("link");queueStyle.rel="stylesheet";queueStyle.href="./course-queue.css";document.head.append(queueStyle);$("#courseGrid").insertAdjacentHTML("afterend",'<section class="hidden" id="courseDetail"></section>');document.querySelector('[data-view="courses"]')?.addEventListener("click",showCourseList);document.addEventListener("click",event=>{if(event.target.closest("[data-course-back]")){showCourseList();return}const edit=event.target.closest("[data-course-edit-map]");if(edit){openCourseEditor(edit.dataset.courseEditMap);return}if(event.target.closest("[data-course-new-unit]")){openCreate("outline");syncCourseSelect(selectedCourseName);return}const prepare=event.target.closest("[data-prepare-course-unit]");if(prepare){const unit=state.units.find(item=>item.id===prepare.dataset.prepareCourseUnit),kind=prepare.dataset.prepareKind;if(!unit)return;if(kind==="analyze"){openCreate(analysisModeForUnit(unit),{targetUnitId:unit.id});syncCourseSelect(unit.course);return}openUnit(unit.id,{returnView:"course",course:selectedCourseName});if(kind==="lesson")$("#unitTabs [data-unit-tab='lesson']")?.click();if(kind==="assessment"||kind==="assessment-quality"||kind==="assessment-set")$("#unitTabs [data-unit-tab='assessment']")?.click();if(kind==="resources")$("#unitTabs [data-unit-tab='resources']")?.click();if(kind==="readiness")$("#readyUnitButton")?.click();return}const move=event.target.closest("[data-move-course-unit]");if(move){const course=state.courses.find(item=>item.name===selectedCourseName);if(course&&moveCourseUnit(course,state.units,move.dataset.moveCourseUnit,Number(move.dataset.direction))){persistCourses();renderCourseMap(course.name);showToast("教学单元顺序已保存")}return}const unit=event.target.closest("[data-open-course-unit]");if(unit)openUnit(unit.dataset.openCourseUnit,{returnView:"course",course:selectedCourseName})});showCourseList()}
