document.addEventListener("click",event=>{
  if(!event.target.closest("#previewCourseBatch"))return;
  setTimeout(()=>{
    const course=state.courses.find(item=>item.name===selectedCourseName);
    if(!course)return;
    const existing=new Set(state.units.filter(unit=>unit.course===course.name).map(unit=>String(unit.title||"").trim().toLocaleLowerCase("zh-CN")));
    $$("#courseBatchPreview .course-batch-row").forEach(row=>{
      const checkbox=row.querySelector("input[type='checkbox']"),title=row.querySelector("input[type='text']");
      if(!existing.has(title.value.trim().toLocaleLowerCase("zh-CN")))return;
      checkbox.checked=false;checkbox.disabled=true;title.disabled=true;row.classList.add("duplicate");
      row.insertAdjacentHTML("beforeend",'<small class="course-batch-existing">已存在</small>');
    });
    const selected=$$("#courseBatchPreview .course-batch-row input[type='checkbox']:checked").length;
    $("#confirmCourseBatch").disabled=!selected;
    $("#confirmCourseBatch").textContent=`创建 ${selected} 个单元`;
  },0);
});

