  document.addEventListener("keydown",event=>{const card=event.target.closest("#courseGrid .course-card[data-course], .asset-card[data-asset-unit]");if(card&&(event.key==="Enter"||event.key===" ")){event.preventDefault();card.click()}});
  const typeCards=$$("#assetsView .asset-type-grid article");typeCards.forEach(card=>{card.tabIndex=0;card.setAttribute("role","button");const filter=()=>{const type=card.querySelector("b")?.textContent.trim();typeCards.forEach(item=>item.classList.toggle("active",item===card));$$("#assetGallery .asset-card").forEach(asset=>asset.hidden=asset.querySelector("span")?.textContent.trim()!==type)};card.onclick=filter;card.onkeydown=event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();filter()}}});
