function setupDiagnosticRunner(){diagnosticRunner=createDiagnosticRunner({getUnit:()=>state.currentUnit,showToast,onComplete:(run,summary)=>{if(state.currentUnit.isDemo){copyDemoUnit()}const unit=state.currentUnit;unit.lesson.diagnosticRuns=[...(Array.isArray(unit.lesson.diagnosticRuns)?unit.lesson.diagnosticRuns:[]),run].slice(-20);const followUps=diagnosticFollowUps(run);followUps.forEach(record=>addInsightImprovement(unit,record));unit.updated="刚刚";recordUnitVersion(unit,"保存课堂诊断记录",`${summary.total} 题 · ${summary.understood} 题多数理解 · ${summary.confused} 题出现误解 · ${summary.incomplete+summary.unobserved} 题未完成${followUps.length?`；已生成 ${followUps.length} 项下一版调整`:""}。`);commitCurrentUnit();renderWorkspace();renderWorkspaceState();renderImprovementPlan();renderVersionHistory(unit);showToast(followUps.length?`诊断已保存，并生成 ${followUps.length} 项课后调整`:"诊断已保存，本轮未发现需要跟进的误解")}})}
function setupUnitDuplication(){const style=document.createElement("link");style.rel="stylesheet";style.href="./unit-duplication.css";document.head.append(style);$("#editUnitButton").insertAdjacentHTML("beforebegin",'<button class="button outline" id="duplicateUnitButton" type="button"><i class="ph ph-copy"></i> 复制单元</button>');document.body.insertAdjacentHTML("beforeend",`<dialog class="create-dialog" id="duplicateUnitDialog"><form method="dialog" class="dialog-shell duplicate-unit-shell"><header><div><span class="section-kicker">DUPLICATE UNIT</span><h2>复制教学单元</h2><p>用于新班级、新学期或相邻章节；复制后两份内容彼此独立。</p></div><button class="dialog-close" value="cancel" aria-label="关闭窗口"><i class="ph ph-x"></i></button></header><div class="dialog-body"><label>新单元标题<input id="duplicateUnitTitle" maxlength="100"></label><label>所属课程<select id="duplicateUnitCourse"></select></label><div class="duplicate-options"><label class="duplicate-option"><input id="duplicateResources" type="checkbox" checked><span><b>复制教学资源</b><small>代码演示、实验任务和教学案例</small></span></label><label class="duplicate-option"><input id="duplicateAnimations" type="checkbox" checked><span><b>复制动效及版本</b><small>保留内容版本，但不继承旧生成任务</small></span></label></div><div class="duplicate-note">课后复盘调整和原单元版本历史不会复制，避免把旧班级数据混入新单元。</div></div><footer><div><button class="button ghost" value="cancel">取消</button><button class="button dark" id="confirmDuplicateUnit" type="button">创建独立副本</button></div></footer></form></dialog>`);const dialog=$("#duplicateUnitDialog");$("#duplicateUnitButton").onclick=()=>{const unit=state.currentUnit,courseNames=[...state.courses.map(course=>course.name),"暂不归入课程"];$("#duplicateUnitTitle").value=`${unit.title||"教学单元"}（副本）`;$("#duplicateUnitCourse").innerHTML=courseNames.map(name=>`<option>${esc(name)}</option>`).join("");$("#duplicateUnitCourse").value=courseNames.includes(unit.course)?unit.course:"暂不归入课程";$("#duplicateResources").checked=true;$("#duplicateAnimations").checked=true;dialog.showModal()};$("#confirmDuplicateUnit").onclick=()=>{const title=$("#duplicateUnitTitle").value.trim();if(!title){showToast("请填写新教学单元标题");return}const source=state.currentUnit,copy=normalizeUnit(duplicateTeachingUnit(source,{title,course:$("#duplicateUnitCourse").value,copyResources:$("#duplicateResources").checked,copyAnimations:$("#duplicateAnimations").checked}));const readiness=assessUnitReadiness(copy);copy.completion=readiness.score;recordUnitVersion(copy,"从教学单元创建独立副本",`来源：${source.title}；教学资源${$("#duplicateResources").checked?"已复制":"未复制"}；动效${$("#duplicateAnimations").checked?"已复制":"未复制"}。`);state.units.unshift(copy);state.currentUnit=copy;persist();renderCollections();dialog.close();openUnit(copy.id);showToast("独立副本已创建，修改不会影响原单元")}}
