  function refresh(){const unit=state.currentUnit,exportButton=$("#exportUnitButton"),assessment=assessUnitReadiness(unit);if(exportButton&&!/导出课堂包/.test(exportButton.textContent))exportButton.innerHTML='<i class="ph ph-share-network"></i> 导出课堂包';unit.completion=assessment.score;button.innerHTML=unit.isDemo?'<i class="ph ph-copy"></i> 复制为我的单元':unit.status==="可授课"?'<i class="ph ph-clipboard-text"></i> 查看授课检查':`<i class="ph ph-check-circle"></i> 授课检查 · ${assessment.score}%`;const list=$("#overviewPanel .readiness-list");if(!list)return;const signature=assessment.sections.map(section=>`${section.id}:${section.score}`).join("|");if(list.dataset.readinessSignature===signature)return;list.dataset.readinessSignature=signature;list.innerHTML=assessment.sections.filter(section=>section.id!=="overview").map(section=>`<div class="readiness-row"><span>${esc(section.label)}</span><b>${section.score}%</b><i><em style="width:${section.score}%"></em></i></div>`).join("")}
  button.onclick=()=>{if(state.currentUnit.isDemo){copyDemoUnit();renderWorkspace();renderWorkspaceState();renderVersionHistory(state.currentUnit);refresh();showToast("体验示例已复制，可以自由修改");return}inspector.open()};
  readinessRefresh=refresh;refresh();
